-- Conteudo editorial das dicas semanais. Pode ser reaplicado com seguranca.
CREATE TABLE IF NOT EXISTS public.baby_tips (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  min_week SMALLINT NOT NULL CHECK (min_week BETWEEN 1 AND 52),
  max_week SMALLINT NOT NULL CHECK (max_week BETWEEN 1 AND 52),
  category TEXT NOT NULL CHECK (
    category IN ('play', 'movement', 'communication', 'oral_health', 'safety', 'caregiver')
  ),
  content_en JSONB NOT NULL,
  content_pt JSONB NOT NULL,
  source_name TEXT NOT NULL,
  source_url TEXT NOT NULL,
  reviewed_at DATE NOT NULL DEFAULT CURRENT_DATE,
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT baby_tips_valid_week_range CHECK (min_week <= max_week),
  CONSTRAINT baby_tips_content_en_shape CHECK (
    content_en ? 'title' AND content_en ? 'body' AND
    (content_en->>'title') <> '' AND (content_en->>'body') <> ''
  ),
  CONSTRAINT baby_tips_content_pt_shape CHECK (
    content_pt ? 'title' AND content_pt ? 'body' AND
    (content_pt->>'title') <> '' AND (content_pt->>'body') <> ''
  )
);

CREATE INDEX IF NOT EXISTS idx_baby_tips_active_week
  ON public.baby_tips (is_active, min_week, max_week, sort_order);

ALTER TABLE public.baby_tips ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Anyone can read active baby tips" ON public.baby_tips;
CREATE POLICY "Anyone can read active baby tips"
  ON public.baby_tips FOR SELECT TO anon, authenticated
  USING (is_active = TRUE);

GRANT SELECT ON public.baby_tips TO anon, authenticated;

INSERT INTO public.baby_tips (
  slug, min_week, max_week, category, content_en, content_pt,
  source_name, source_url, reviewed_at, sort_order, is_active
)
SELECT
  seed.slug,
  seed.week,
  seed.week,
  seed.category,
  seed.content_en,
  seed.content_pt,
  seed.source_name,
  seed.source_url,
  DATE '2026-10-14',
  seed.week,
  TRUE
FROM jsonb_to_recordset($tips$
[
  {"slug":"week-01-responsive-cuddles","week":1,"category":"caregiver","source_name":"CDC — 2-month tips","source_url":"https://www.cdc.gov/act-early/milestones/2-months.html","content_en":{"title":"Notice your baby's cues","body":"Your baby communicates through sounds, movement, and facial expressions. Responding when you can helps build a sense of safety and connection.","activity":"During a calm moment, look at your baby, speak softly, and pause to notice their response."},"content_pt":{"title":"Observe os sinais do bebê","body":"Seu bebê se comunica por sons, movimentos e expressões. Responder quando possível ajuda a criar segurança e conexão.","activity":"Em um momento tranquilo, olhe para o bebê, fale baixinho e faça uma pausa para perceber a resposta."}},
  {"slug":"week-02-talk-and-sing","week":2,"category":"communication","source_name":"CDC — 2-month tips","source_url":"https://www.cdc.gov/act-early/milestones/2-months.html","content_en":{"title":"Talk and sing during everyday care","body":"Simple conversations, songs, and familiar voices make ordinary care moments a chance to connect.","activity":"Tell your baby what you are doing while dressing or changing them."},"content_pt":{"title":"Converse e cante nos cuidados do dia","body":"Conversas simples, canções e vozes conhecidas transformam os cuidados comuns em momentos de conexão.","activity":"Conte ao bebê o que você está fazendo enquanto troca ou veste a roupa dele."}},
  {"slug":"week-03-face-time","week":3,"category":"play","source_name":"CDC — 2-month tips","source_url":"https://www.cdc.gov/act-early/milestones/2-months.html","content_en":{"title":"Share a quiet face-to-face moment","body":"Babies enjoy looking at faces. A calm moment close to you can be a simple way to connect.","activity":"When your baby is calm and alert, get comfortably close and smile or talk gently."},"content_pt":{"title":"Tenham um momento tranquilo frente a frente","body":"Bebês gostam de observar rostos. Um momento calmo perto de você pode ser uma forma simples de se conectar.","activity":"Quando o bebê estiver tranquilo e alerta, aproxime-se confortavelmente e sorria ou converse com suavidade."}},
  {"slug":"week-04-tummy-time-start","week":4,"category":"movement","source_name":"NHS — tummy time","source_url":"https://www.nhs.uk/baby/babys-development/play-and-learning/keep-baby-or-toddler-active/","content_en":{"title":"Try a little supervised tummy time","body":"Tummy time is for awake, alert babies with an adult watching closely. Starting with short, comfortable moments is fine.","activity":"Try tummy time on your chest while you are fully awake, or on a clear floor mat with your baby in sight."},"content_pt":{"title":"Experimente um pouco de tummy time supervisionado","body":"Tummy time é para o bebê acordado e alerta, sempre observado por um adulto. Tudo bem começar com períodos curtos e confortáveis.","activity":"Experimente com o bebê sobre seu peito enquanto você está bem acordada, ou em um tapete livre no chão, sempre à vista."}},
  {"slug":"week-05-follow-a-face","week":5,"category":"play","source_name":"CDC — 2-month milestones","source_url":"https://www.cdc.gov/act-early/milestones/2-months.html","content_en":{"title":"Let your baby watch you move","body":"Watching a familiar face move across a small space can invite your baby to look and pay attention.","activity":"While your baby is lying safely on their back, slowly move your face from one side to the other and speak gently."},"content_pt":{"title":"Deixe o bebê acompanhar você com o olhar","body":"Observar um rosto conhecido se mover por uma curta distância pode convidar o bebê a olhar e prestar atenção.","activity":"Com o bebê deitado com segurança de costas, mova seu rosto devagar de um lado para o outro enquanto conversa."}},
  {"slug":"week-06-short-floor-play","week":6,"category":"movement","source_name":"WHO — under-5 activity guidelines","source_url":"https://www.who.int/EN/news-room/detail/24-04-2019-to-grow-up-healthy-children-need-to-sit-less-and-play-more","content_en":{"title":"Make room for floor play","body":"For babies who are not yet mobile, the WHO recommends varied, interactive floor-based activity throughout the day, including supervised tummy time while awake.","activity":"Offer a few short, relaxed floor-play moments while your baby is awake and you are right there."},"content_pt":{"title":"Reserve espaço para brincar no chão","body":"Para bebês que ainda não se locomovem, a OMS recomenda atividades variadas e interativas no chão ao longo do dia, incluindo tummy time supervisionado enquanto acordados.","activity":"Ofereça alguns momentos curtos e tranquilos de brincadeira no chão, com o bebê acordado e você por perto."}},
  {"slug":"week-07-talk-back","week":7,"category":"communication","source_name":"CDC — 2-month tips","source_url":"https://www.cdc.gov/act-early/milestones/2-months.html","content_en":{"title":"Pause for a little back-and-forth","body":"When your baby makes a sound, responding with a smile or a few words can turn it into an early conversation.","activity":"Copy a sound your baby makes, then pause and give them time to respond in their own way."},"content_pt":{"title":"Façam pequenas pausas para conversar","body":"Quando o bebê fizer um som, responder com um sorriso ou algumas palavras pode iniciar uma conversa.","activity":"Imite um som do bebê, faça uma pausa e dê tempo para ele responder à sua maneira."}},
  {"slug":"week-08-picture-looking","week":8,"category":"play","source_name":"CDC — 2-month tips","source_url":"https://www.cdc.gov/act-early/milestones/2-months.html","content_en":{"title":"Look at a picture together","body":"A simple picture gives you something to look at and talk about together. Keep the moment relaxed and follow your baby's attention.","activity":"Show one colorful picture or a baby-safe book page and name what you see."},"content_pt":{"title":"Olhem uma imagem juntos","body":"Uma imagem simples dá a vocês algo para observar e comentar. Mantenha o momento tranquilo e acompanhe a atenção do bebê.","activity":"Mostre uma imagem colorida ou uma página de livro apropriada para bebês e nomeie o que estão vendo."}},
  {"slug":"week-09-smile-and-respond","week":9,"category":"communication","source_name":"CDC — 2-month tips","source_url":"https://www.cdc.gov/act-early/milestones/2-months.html","content_en":{"title":"Answer your baby's sounds with warmth","body":"Smiling and speaking when your baby makes sounds supports enjoyable back-and-forth interaction.","activity":"When you hear a coo or another sound, smile, answer softly, and leave a little pause."},"content_pt":{"title":"Responda aos sons do bebê com carinho","body":"Sorrir e conversar quando o bebê faz sons favorece uma interação gostosa de ida e volta.","activity":"Ao ouvir um balbucio ou outro som, sorria, responda com suavidade e faça uma pequena pausa."}},
  {"slug":"week-10-rattle-sound","week":10,"category":"play","source_name":"CDC — 2-month tips","source_url":"https://www.cdc.gov/act-early/milestones/2-months.html","content_en":{"title":"Listen together","body":"A gentle sound can invite your baby to notice where a voice or object is coming from.","activity":"From nearby, softly call your baby's name or shake a baby-safe rattle once, then pause and watch."},"content_pt":{"title":"Escutem os sons juntos","body":"Um som suave pode convidar o bebê a perceber de onde vem uma voz ou um objeto.","activity":"Perto do bebê, chame-o suavemente ou balance uma vez um chocalho seguro para a idade; depois observe."}},
  {"slug":"week-11-comforting-routine","week":11,"category":"caregiver","source_name":"CDC — 2-month tips","source_url":"https://www.cdc.gov/act-early/milestones/2-months.html","content_en":{"title":"Find a soothing routine that works for you","body":"Noticing what comforts your baby can make daily care feel more predictable for both of you.","activity":"Try a familiar gentle voice, cuddle, or song, and notice which cues help your baby settle."},"content_pt":{"title":"Encontre um jeito acolhedor que funcione para vocês","body":"Perceber o que conforta o bebê pode deixar os cuidados diários mais previsíveis para vocês dois.","activity":"Experimente uma voz familiar, colo ou canção suave e observe quais sinais ajudam o bebê a se acalmar."}},
  {"slug":"week-12-safe-mirror","week":12,"category":"play","source_name":"CDC — 2-month tips","source_url":"https://www.cdc.gov/act-early/milestones/2-months.html","content_en":{"title":"Explore a baby-safe mirror","body":"Babies may enjoy looking at faces and reflections. Keep the mirror securely placed and made for baby use.","activity":"During supervised floor play, position a baby-safe mirror where your baby can see it."},"content_pt":{"title":"Explore um espelho seguro para bebês","body":"Bebês podem gostar de observar rostos e reflexos. Use um espelho próprio para bebês, colocado com segurança.","activity":"Durante uma brincadeira supervisionada no chão, posicione o espelho onde o bebê possa vê-lo."}},
  {"slug":"week-13-read-and-talk","week":13,"category":"communication","source_name":"CDC — 2-month tips","source_url":"https://www.cdc.gov/act-early/milestones/2-months.html","content_en":{"title":"Make a book part of your day","body":"Reading can be as simple as looking at pictures and hearing your voice. There is no need to finish a whole book.","activity":"Choose one page, point to a picture, and describe it in a calm voice."},"content_pt":{"title":"Inclua um livro no dia de vocês","body":"Ler pode ser simplesmente olhar imagens e ouvir sua voz. Não é preciso terminar o livro todo.","activity":"Escolha uma página, aponte para uma imagem e descreva-a com calma."}},
  {"slug":"week-14-track-slow-toy","week":14,"category":"play","source_name":"CDC — 4-month activities","source_url":"https://www.cdc.gov/act-early/milestones/4-months.html","content_en":{"title":"Invite your baby to follow a toy","body":"A slowly moving, baby-safe toy can invite your baby to look and follow it during awake floor play.","activity":"With your baby safely on their back, move a colorful toy slowly from side to side. Stop if they seem tired."},"content_pt":{"title":"Convide o bebê a acompanhar um brinquedo","body":"Um brinquedo colorido e seguro, movido devagar, pode convidar o bebê a observá-lo durante uma brincadeira acordado no chão.","activity":"Com o bebê seguro de costas, mova um brinquedo colorido lentamente de um lado para o outro. Pare se ele parecer cansado."}},
  {"slug":"week-15-reach-and-kick","week":15,"category":"movement","source_name":"CDC — 4-month activities","source_url":"https://www.cdc.gov/act-early/milestones/4-months.html","content_en":{"title":"Offer space to reach and kick","body":"Safe open floor space gives your baby a chance to move arms and legs and explore nearby toys.","activity":"Place one large, age-appropriate toy within comfortable reach while your baby is supervised on a clear mat."},"content_pt":{"title":"Ofereça espaço para alcançar e chutar","body":"Um espaço livre e seguro no chão dá ao bebê a chance de mexer braços e pernas e explorar brinquedos por perto.","activity":"Coloque um brinquedo grande e apropriado para a idade ao alcance confortável do bebê, supervisionando-o no tapete livre."}},
  {"slug":"week-16-copy-baby-sounds","week":16,"category":"communication","source_name":"CDC — 4-month activities","source_url":"https://www.cdc.gov/act-early/milestones/4-months.html","content_en":{"title":"Copy a sound, then add a word","body":"Taking turns with sounds is a playful way to connect. Your baby does not need to copy you for the exchange to count.","activity":"Repeat a sound your baby makes, then add a simple word and wait."},"content_pt":{"title":"Imite um som e acrescente uma palavra","body":"Alternar sons é uma forma divertida de se conectar. O bebê não precisa imitar você para a troca valer.","activity":"Repita um som do bebê, acrescente uma palavra simples e espere um pouco."}},
  {"slug":"week-17-safe-grasp","week":17,"category":"play","source_name":"CDC — 4-month activities","source_url":"https://www.cdc.gov/act-early/milestones/4-months.html","content_en":{"title":"Offer an easy-to-hold toy","body":"A lightweight baby-safe rattle or soft book can give your baby a chance to explore holding and touching.","activity":"Place the toy in your baby's hand or within reach while you stay close and supervise."},"content_pt":{"title":"Ofereça um brinquedo fácil de segurar","body":"Um chocalho leve e seguro ou um livrinho macio dá ao bebê a chance de explorar o toque e a preensão.","activity":"Coloque o brinquedo na mão do bebê ou ao alcance dele, ficando perto e supervisionando."}},
  {"slug":"week-18-peekaboo","week":18,"category":"play","source_name":"CDC — 4-month activities","source_url":"https://www.cdc.gov/act-early/milestones/4-months.html","content_en":{"title":"Play a gentle peekaboo game","body":"A familiar face appearing and disappearing can make a simple, social game. Follow your baby's mood and stop if they lose interest.","activity":"Cover your face with your hands, uncover it, and say “peekaboo!”"},"content_pt":{"title":"Brinque de escondeu-achou","body":"Um rosto conhecido que aparece e desaparece vira uma brincadeira social simples. Acompanhe o humor do bebê e pare se ele perder o interesse.","activity":"Cubra o rosto com as mãos, descubra-o e diga “achou!”"}},
  {"slug":"week-19-sing-and-move","week":19,"category":"movement","source_name":"CDC — 4-month activities","source_url":"https://www.cdc.gov/act-early/milestones/4-months.html","content_en":{"title":"Pair a familiar song with gentle movement","body":"Talking and singing during play can make movement feel engaging without turning it into an exercise task.","activity":"Sing a short song while your baby moves freely on a safe floor mat."},"content_pt":{"title":"Junte uma canção conhecida a movimentos suaves","body":"Conversar e cantar durante a brincadeira pode tornar o movimento divertido, sem transformá-lo em exercício obrigatório.","activity":"Cante uma música curta enquanto o bebê se movimenta livremente em um tapete seguro."}},
  {"slug":"week-20-quiet-play","week":20,"category":"play","source_name":"CDC — 4-month activities","source_url":"https://www.cdc.gov/act-early/milestones/4-months.html","content_en":{"title":"Leave room for quiet play","body":"Babies also benefit from calm moments to look, listen, and rest. You can pause when your baby turns away or seems overstimulated.","activity":"Sit together with a soft book or song and let your baby set the pace."},"content_pt":{"title":"Reserve um tempo para brincar com calma","body":"Momentos tranquilos também permitem ao bebê olhar, escutar e descansar. Faça uma pausa se ele desviar o olhar ou parecer estimulado demais.","activity":"Fiquem juntos com um livro macio ou uma canção e deixe o bebê ditar o ritmo."}},
  {"slug":"week-21-safe-textures","week":21,"category":"play","source_name":"CDC — 4-month activities","source_url":"https://www.cdc.gov/act-early/milestones/4-months.html","content_en":{"title":"Explore safe textures together","body":"Touching different safe materials can make floor play interesting. Avoid anything hot, sharp, loose, or small enough to choke on.","activity":"Let your baby touch a clean, large piece of soft fabric while you supervise closely."},"content_pt":{"title":"Explore texturas seguras juntos","body":"Tocar materiais seguros variados pode deixar a brincadeira no chão mais interessante. Evite itens quentes, pontiagudos, soltos ou pequenos o bastante para causar engasgo.","activity":"Deixe o bebê tocar um tecido macio, limpo e grande enquanto você supervisiona de perto."}},
  {"slug":"week-22-name-and-smile","week":22,"category":"communication","source_name":"CDC — 4-month activities","source_url":"https://www.cdc.gov/act-early/milestones/4-months.html","content_en":{"title":"Use your baby's name in conversation","body":"Hearing familiar words during warm, face-to-face interaction is a simple way to make everyday talk personal.","activity":"Say your baby's name, smile, and describe what you are doing together."},"content_pt":{"title":"Use o nome do bebê na conversa","body":"Ouvir palavras familiares em uma interação carinhosa e frente a frente torna a conversa do dia a dia mais pessoal.","activity":"Diga o nome do bebê, sorria e conte o que vocês estão fazendo juntos."}},
  {"slug":"week-23-floor-time","week":23,"category":"movement","source_name":"NHS — tummy time","source_url":"https://www.nhs.uk/baby/babys-development/play-and-learning/keep-baby-or-toddler-active/","content_en":{"title":"Choose floor play over long periods in a seat","body":"The NHS encourages babies to move and interact with people and objects, and advises against spending too long in seats or bouncers.","activity":"When practical, offer a supervised floor-play break between time in a stroller or seat."},"content_pt":{"title":"Prefira a brincadeira no chão a longos períodos sentado","body":"O NHS incentiva os bebês a se movimentarem e interagirem com pessoas e objetos, evitando muito tempo em cadeirinhas ou balanços.","activity":"Quando possível, ofereça uma pausa para brincar no chão, com supervisão, entre os períodos no carrinho ou assento."}},
  {"slug":"week-24-turn-taking","week":24,"category":"communication","source_name":"CDC — 4-month activities","source_url":"https://www.cdc.gov/act-early/milestones/4-months.html","content_en":{"title":"Take turns during play","body":"A pause after you speak or make a sound gives your baby time to respond with a look, movement, or sound.","activity":"Say a short phrase, wait, then respond to whatever your baby does next."},"content_pt":{"title":"Revezem-se durante a brincadeira","body":"Uma pausa depois de você falar ou fazer um som dá tempo para o bebê responder com olhar, movimento ou som.","activity":"Diga uma frase curta, espere e responda ao que o bebê fizer em seguida."}},
  {"slug":"week-25-supervised-tummy-time","week":25,"category":"movement","source_name":"WHO — under-5 activity guidelines","source_url":"https://www.who.int/EN/news-room/detail/24-04-2019-to-grow-up-healthy-children-need-to-sit-less-and-play-more","content_en":{"title":"Keep awake tummy time supervised","body":"For babies not yet mobile, WHO guidance includes at least 30 minutes of tummy time spread through the day while awake. Build toward this with comfortable opportunities and close supervision.","activity":"Offer a few short sessions across the day; stop when your baby is tired or uncomfortable."},"content_pt":{"title":"Mantenha o tummy time supervisionado e com o bebê acordado","body":"Para bebês que ainda não se locomovem, a OMS inclui pelo menos 30 minutos de tummy time distribuídos ao longo do dia e enquanto acordados. Aumente aos poucos, respeitando o conforto e supervisionando de perto.","activity":"Ofereça algumas sessões curtas ao longo do dia; pare se o bebê ficar cansado ou desconfortável."}},
  {"slug":"week-26-roll-toy","week":26,"category":"movement","source_name":"CDC — 6-month activities","source_url":"https://www.cdc.gov/act-early/milestones/6-months.html","content_en":{"title":"Make space for rolling practice","body":"Rolling from tummy to back is a CDC milestone by 6 months for most babies, but each baby develops at their own pace. Offer safe floor space without trying to force a movement.","activity":"During awake, supervised floor play, place a baby-safe toy nearby and let your baby choose whether to reach or turn."},"content_pt":{"title":"Abra espaço para explorar movimentos de rolar","body":"Rolar da barriga para as costas é um marco do CDC observado até os 6 meses pela maioria dos bebês, mas cada bebê se desenvolve no seu ritmo. Ofereça um espaço seguro no chão sem forçar movimentos.","activity":"Durante a brincadeira supervisionada e com o bebê acordado, deixe um brinquedo seguro por perto e permita que ele escolha se quer alcançar ou virar."}},
  {"slug":"week-27-respond-to-babble","week":27,"category":"communication","source_name":"CDC — 6-month activities","source_url":"https://www.cdc.gov/act-early/milestones/6-months.html","content_en":{"title":"Answer babbles as if chatting","body":"Back-and-forth sounds are a playful way to connect and encourage communication.","activity":"Repeat a sound your baby makes, add a simple word, and smile while you wait for another turn."},"content_pt":{"title":"Responda aos balbucios como numa conversa","body":"Trocar sons é uma forma divertida de se conectar e incentivar a comunicação.","activity":"Repita um som do bebê, acrescente uma palavra simples e sorria enquanto espera a próxima vez."}},
  {"slug":"week-28-teething-varies","week":28,"category":"oral_health","source_name":"NHS — teething symptoms","source_url":"https://www.nhs.uk/conditions/baby/babys-development/teething/baby-teething-symptoms/","content_en":{"title":"Remember that teething timing varies","body":"Many babies get a first tooth around 6 months, but timing varies widely. Teething does not explain every symptom; contact a health professional if something concerns you.","activity":"If you notice a tooth emerging, make a note and ask your health visitor or dentist about oral-care advice."},"content_pt":{"title":"Lembre-se de que a dentição varia","body":"Muitos bebês têm o primeiro dente por volta dos 6 meses, mas o momento varia bastante. Nem todo sintoma é causado pela dentição; procure orientação se algo preocupar você.","activity":"Se notar um dente aparecendo, anote e peça orientação sobre cuidados orais ao profissional de saúde ou dentista."}},
  {"slug":"week-29-first-tooth-care","week":29,"category":"oral_health","source_name":"NHS — baby teeth care","source_url":"https://www.nhs.uk/baby/babys-development/teething/looking-after-your-babys-teeth/","content_en":{"title":"Start a gentle tooth-brushing routine when a tooth appears","body":"The NHS advises brushing as soon as the first milk tooth comes through, using a baby toothbrush and a tiny smear of fluoride toothpaste. Follow local dental guidance.","activity":"Let your baby see you brush your teeth, then gently introduce their own brush as part of a calm routine."},"content_pt":{"title":"Comece uma rotina suave de escovação quando surgir o primeiro dente","body":"O NHS orienta começar a escovar assim que o primeiro dente de leite aparecer, com escova infantil e uma pequena quantidade de pasta com flúor. Siga as orientações odontológicas locais.","activity":"Deixe o bebê ver você escovar os dentes e depois apresente a escova dele com calma, como parte da rotina."}},
  {"slug":"week-30-picture-names","week":30,"category":"communication","source_name":"CDC — 6-month activities","source_url":"https://www.cdc.gov/act-early/milestones/6-months.html","content_en":{"title":"Name what catches your baby's attention","body":"Following your baby's gaze and naming what they are looking at connects words to shared experiences.","activity":"When your baby looks at a familiar object, point to it and say its name."},"content_pt":{"title":"Dê nome ao que chama a atenção do bebê","body":"Acompanhar o olhar do bebê e nomear o que ele observa conecta palavras a experiências compartilhadas.","activity":"Quando o bebê olhar para um objeto conhecido, aponte para ele e diga o nome."}},
  {"slug":"week-31-book-pictures","week":31,"category":"communication","source_name":"CDC — 6-month activities","source_url":"https://www.cdc.gov/act-early/milestones/6-months.html","content_en":{"title":"Read pictures, not just words","body":"A book can be a conversation even before your baby understands its words. Pointing and naming pictures makes reading interactive.","activity":"Look at one or two pictures together and describe them in your own words."},"content_pt":{"title":"Leiam as imagens, não só as palavras","body":"Um livro pode ser uma conversa antes mesmo de o bebê entender as palavras. Apontar e nomear figuras torna a leitura interativa.","activity":"Olhem juntos uma ou duas imagens e descreva-as com suas palavras."}},
  {"slug":"week-32-safe-reaching","week":32,"category":"movement","source_name":"CDC — 6-month activities","source_url":"https://www.cdc.gov/act-early/milestones/6-months.html","content_en":{"title":"Invite reaching during floor play","body":"Reaching for a toy is a chance to explore movement. Keep toys age-appropriate and supervise closely to avoid choking hazards.","activity":"Place a large, baby-safe toy just within comfortable reach while your baby is on a clear floor mat."},"content_pt":{"title":"Convide o bebê a alcançar durante a brincadeira","body":"Alcançar um brinquedo é uma oportunidade para explorar movimentos. Escolha itens apropriados para a idade e supervisione para evitar risco de engasgo.","activity":"Deixe um brinquedo grande e seguro ao alcance confortável do bebê sobre um tapete livre no chão."}},
  {"slug":"week-33-hide-and-find","week":33,"category":"play","source_name":"CDC — 9-month activities","source_url":"https://www.cdc.gov/act-early/milestones/9-months.html","content_en":{"title":"Play a simple hide-and-find game","body":"Looking for a toy you briefly hide can turn everyday play into a shared discovery. Keep the game supervised and use a large safe toy.","activity":"Hide a toy partly behind your hand, then reveal it and celebrate together."},"content_pt":{"title":"Brinque de esconder e encontrar","body":"Procurar um brinquedo escondido por um instante transforma a brincadeira em uma descoberta compartilhada. Supervisione e use um brinquedo grande e seguro.","activity":"Esconda parcialmente um brinquedo atrás da mão, depois revele-o e comemorem juntos."}},
  {"slug":"week-34-pass-a-toy","week":34,"category":"play","source_name":"CDC — 9-month activities","source_url":"https://www.cdc.gov/act-early/milestones/9-months.html","content_en":{"title":"Try a my-turn, your-turn game","body":"Passing a toy back and forth gives you a simple way to share attention and take turns.","activity":"Offer a large soft toy, invite your baby to hold it, then hold out your hand and say “my turn” gently."},"content_pt":{"title":"Experimentem uma brincadeira de revezar","body":"Passar um brinquedo de um para o outro é uma forma simples de compartilhar atenção e se revezar.","activity":"Ofereça um brinquedo macio e grande; depois estenda a mão e diga “minha vez” com suavidade."}},
  {"slug":"week-35-copy-sounds","week":35,"category":"communication","source_name":"CDC — 9-month activities","source_url":"https://www.cdc.gov/act-early/milestones/9-months.html","content_en":{"title":"Repeat your baby's sounds and add a word","body":"Repeating a sound and pairing it with a simple word makes a playful conversation. There is no need to quiz your baby.","activity":"If your baby babbles, echo the sound and add a familiar word such as “book” or “ball.”"},"content_pt":{"title":"Repita os sons do bebê e acrescente uma palavra","body":"Repetir um som e juntá-lo a uma palavra simples vira uma conversa divertida. Não é preciso fazer perguntas como teste.","activity":"Se o bebê balbuciar, imite o som e acrescente uma palavra familiar, como “livro” ou “bola”."}},
  {"slug":"week-36-drop-and-return","week":36,"category":"play","source_name":"CDC — 9-month activities","source_url":"https://www.cdc.gov/act-early/milestones/9-months.html","content_en":{"title":"Turn dropping into a game","body":"Babies may enjoy seeing what happens when an object falls. A safe, large toy and a clear floor keep this exploration manageable.","activity":"During supervised play, pick up and return a soft toy once or twice, then follow your baby's lead."},"content_pt":{"title":"Transforme deixar cair em uma brincadeira","body":"Bebês podem gostar de observar o que acontece quando um objeto cai. Um brinquedo grande e seguro e o chão livre ajudam a manter a brincadeira adequada.","activity":"Durante a supervisão, pegue e devolva um brinquedo macio uma ou duas vezes, acompanhando o interesse do bebê."}},
  {"slug":"week-37-wave-hello","week":37,"category":"communication","source_name":"CDC — 9-month activities","source_url":"https://www.cdc.gov/act-early/milestones/9-months.html","content_en":{"title":"Add a wave to familiar goodbyes","body":"Gestures paired with words make everyday interactions clear and warm. Your baby can simply watch; copying is not required.","activity":"Wave and say “bye-bye” when someone leaves, keeping the moment relaxed."},"content_pt":{"title":"Acompanhe despedidas conhecidas com um gesto","body":"Gestos junto com palavras tornam as interações cotidianas claras e carinhosas. O bebê pode apenas observar; não precisa imitar.","activity":"Acene e diga “tchau” quando alguém sair, sem transformar o momento em cobrança."}},
  {"slug":"week-38-safe-exploration","week":38,"category":"safety","source_name":"CDC — 9-month activities","source_url":"https://www.cdc.gov/act-early/milestones/9-months.html","content_en":{"title":"Make a small space safe to explore","body":"As babies become more mobile, a clear, supervised play area lets them explore while hazards stay out of reach.","activity":"Get down to your baby's level and move small, sharp, breakable, or unsafe items away."},"content_pt":{"title":"Prepare um espaço pequeno e seguro para explorar","body":"Quando os bebês ficam mais móveis, uma área livre e supervisionada permite explorar com perigos fora do alcance.","activity":"Fique na altura do bebê e retire do espaço itens pequenos, pontiagudos, quebráveis ou perigosos."}},
  {"slug":"week-39-name-the-feeling","week":39,"category":"communication","source_name":"CDC — 9-month activities","source_url":"https://www.cdc.gov/act-early/milestones/9-months.html","content_en":{"title":"Put simple words to feelings","body":"Naming a baby's visible feelings can help you respond with warmth and show that you are paying attention.","activity":"If your baby seems frustrated, try saying “That was hard; I'm here” in a calm voice."},"content_pt":{"title":"Dê palavras simples aos sentimentos","body":"Nomear o que o bebê parece sentir pode ajudar você a responder com carinho e mostrar que está presente.","activity":"Se o bebê parecer frustrado, tente dizer “Foi difícil; estou aqui” com voz tranquila."}},
  {"slug":"week-40-book-conversation","week":40,"category":"communication","source_name":"CDC — 9-month activities","source_url":"https://www.cdc.gov/act-early/milestones/9-months.html","content_en":{"title":"Let your baby help tell the story","body":"Reading together can mean pointing, making sounds, or naming pictures rather than reading every word.","activity":"Pause on a picture your baby notices and describe it together."},"content_pt":{"title":"Deixe o bebê participar da história","body":"Ler juntos pode ser apontar, fazer sons ou nomear figuras, sem precisar ler todas as palavras.","activity":"Faça uma pausa na imagem que chamar a atenção do bebê e conversem sobre ela."}},
  {"slug":"week-41-imitate-actions","week":41,"category":"play","source_name":"CDC — 1-year activities","source_url":"https://www.cdc.gov/act-early/milestones/1-year.html","content_en":{"title":"Take turns copying simple actions","body":"Simple actions such as clapping can become a social game. Enjoy any response, including watching or smiling.","activity":"Clap slowly, pause, and invite your baby to join if they want."},"content_pt":{"title":"Imitem gestos simples em turnos","body":"Gestos simples, como bater palmas, podem virar uma brincadeira social. Aproveite qualquer resposta, inclusive só olhar ou sorrir.","activity":"Bata palmas devagar, faça uma pausa e convide o bebê a participar se quiser."}},
  {"slug":"week-42-large-blocks","week":42,"category":"play","source_name":"CDC — 9-month activities","source_url":"https://www.cdc.gov/act-early/milestones/9-months.html","content_en":{"title":"Fill and empty with large blocks","body":"Putting large, baby-safe blocks into and out of a sturdy container can make a satisfying play activity. Stay close and avoid small pieces.","activity":"Offer a few large blocks and a light container; show putting one in, then let your baby explore."},"content_pt":{"title":"Coloque e retire blocos grandes","body":"Colocar e tirar blocos grandes e seguros de um recipiente firme pode ser uma brincadeira interessante. Fique por perto e evite peças pequenas.","activity":"Ofereça alguns blocos grandes e um recipiente leve; mostre como colocar um e depois deixe o bebê explorar."}},
  {"slug":"week-43-point-and-name","week":43,"category":"communication","source_name":"CDC — 9-month activities","source_url":"https://www.cdc.gov/act-early/milestones/9-months.html","content_en":{"title":"Point and name familiar things","body":"Describing what your baby is looking at connects words to the world around them.","activity":"Follow your baby's gaze, point to the object, and say one or two simple words about it."},"content_pt":{"title":"Aponte e nomeie coisas conhecidas","body":"Descrever o que o bebê está observando conecta palavras ao mundo ao redor.","activity":"Acompanhe o olhar do bebê, aponte para o objeto e diga uma ou duas palavras simples sobre ele."}},
  {"slug":"week-44-routine-and-goodbye","week":44,"category":"caregiver","source_name":"CDC — 9-month activities","source_url":"https://www.cdc.gov/act-early/milestones/9-months.html","content_en":{"title":"Keep everyday routines warm and predictable","body":"Familiar routines and clear goodbyes can help babies know what to expect. It is okay if transitions still bring big feelings.","activity":"Use the same short goodbye phrase when you leave, then greet your baby warmly when you return."},"content_pt":{"title":"Mantenha as rotinas acolhedoras e previsíveis","body":"Rotinas familiares e despedidas claras ajudam o bebê a saber o que esperar. Tudo bem se as transições ainda trouxerem emoções fortes.","activity":"Use a mesma frase curta ao sair e cumprimente o bebê com carinho quando voltar."}},
  {"slug":"week-45-music-and-gestures","week":45,"category":"play","source_name":"CDC — 1-year activities","source_url":"https://www.cdc.gov/act-early/milestones/1-year.html","content_en":{"title":"Add gestures to a familiar song","body":"Songs with simple actions create an easy moment to share sounds, movement, and attention.","activity":"Sing a familiar short song and add one gentle gesture, such as waving."},"content_pt":{"title":"Acrescente gestos a uma canção conhecida","body":"Canções com ações simples criam um momento fácil para compartilhar sons, movimento e atenção.","activity":"Cante uma música curta e conhecida e acrescente um gesto suave, como acenar."}},
  {"slug":"week-46-toy-search","week":46,"category":"play","source_name":"CDC — 1-year activities","source_url":"https://www.cdc.gov/act-early/milestones/1-year.html","content_en":{"title":"Help your baby look for a toy","body":"A toy briefly hidden in plain sight can invite a small search-and-find game. Keep the game supervised and the toy large and safe.","activity":"Partly cover a familiar toy with your hand, then uncover it together."},"content_pt":{"title":"Ajude o bebê a procurar um brinquedo","body":"Um brinquedo escondido por um instante, mas ainda à vista, pode iniciar uma brincadeira de procurar. Supervisione e escolha um brinquedo grande e seguro.","activity":"Cubra parcialmente um brinquedo conhecido com a mão e depois descubram-no juntos."}},
  {"slug":"week-47-safe-standing-space","week":47,"category":"safety","source_name":"CDC — 9-month activities","source_url":"https://www.cdc.gov/act-early/milestones/9-months.html","content_en":{"title":"Check the space around new movement","body":"Babies explore movement in different ways and on different timelines. Keep nearby furniture stable and stay close as your baby plays.","activity":"Check the floor and nearby furniture for tipping, sharp edges, cords, or small objects before play."},"content_pt":{"title":"Revise o espaço para novos movimentos","body":"Bebês exploram movimentos de jeitos e em momentos diferentes. Mantenha móveis próximos estáveis e fique por perto durante a brincadeira.","activity":"Antes de brincar, confira o chão e os móveis próximos para evitar tombamentos, quinas, fios e objetos pequenos."}},
  {"slug":"week-48-brush-first-teeth","week":48,"category":"oral_health","source_name":"NHS — baby teeth care","source_url":"https://www.nhs.uk/baby/babys-development/teething/looking-after-your-babys-teeth/","content_en":{"title":"Make tooth brushing familiar","body":"If teeth have appeared, the NHS recommends starting to brush with a baby toothbrush and a tiny smear of fluoride toothpaste. Follow your local dental guidance.","activity":"Brush together at a calm time so your baby can watch and get used to the routine."},"content_pt":{"title":"Torne a escovação familiar","body":"Se os dentes já apareceram, o NHS recomenda começar a escovar com escova infantil e uma pequena quantidade de pasta com flúor. Siga a orientação odontológica local.","activity":"Escovem juntos em um momento tranquilo para o bebê observar e se acostumar com a rotina."}},
  {"slug":"week-49-clap-and-pause","week":49,"category":"communication","source_name":"CDC — 1-year activities","source_url":"https://www.cdc.gov/act-early/milestones/1-year.html","content_en":{"title":"Play a simple copy-me game","body":"A familiar gesture such as clapping can be fun to share. Let your baby watch or respond in their own way.","activity":"Clap once, smile, pause, and see whether your baby wants another turn."},"content_pt":{"title":"Brinque de imitar um gesto","body":"Um gesto conhecido, como bater palmas, pode ser divertido de compartilhar. Deixe o bebê observar ou responder à sua maneira.","activity":"Bata palmas uma vez, sorria, faça uma pausa e veja se o bebê quer outra vez."}},
  {"slug":"week-50-pat-a-cake","week":50,"category":"play","source_name":"CDC — 1-year milestones","source_url":"https://www.cdc.gov/act-early/milestones/1-year.html","content_en":{"title":"Share a familiar hand game","body":"The CDC includes simple back-and-forth games such as pat-a-cake among social play ideas around one year. Enjoy the interaction without expecting a particular response.","activity":"Sing a short hand-clapping rhyme together, moving gently and following your baby's interest."},"content_pt":{"title":"Compartilhem uma brincadeira de mãos conhecida","body":"O CDC cita brincadeiras simples de ida e volta, como bater palminhas, entre as ideias de interação por volta de um ano. Aproveite a troca sem esperar uma resposta específica.","activity":"Cantem juntos uma parlenda curta com palmas suaves, acompanhando o interesse do bebê."}},
  {"slug":"week-51-container-play","week":51,"category":"play","source_name":"CDC — 1-year activities","source_url":"https://www.cdc.gov/act-early/milestones/1-year.html","content_en":{"title":"Explore putting a toy in a container","body":"A sturdy container and a large safe toy can support simple in-and-out play. Stay nearby and make sure all pieces are too large to choke on.","activity":"Show your baby how to place one large block inside, then take it out together."},"content_pt":{"title":"Explore colocar um brinquedo dentro de um recipiente","body":"Um recipiente firme e um brinquedo grande e seguro podem render uma brincadeira simples de colocar e tirar. Fique por perto e confira se as peças não oferecem risco de engasgo.","activity":"Mostre como colocar um bloco grande dentro e depois tirem-no juntos."}},
  {"slug":"week-52-celebrate-connection","week":52,"category":"caregiver","source_name":"CDC — 1-year activities","source_url":"https://www.cdc.gov/act-early/milestones/1-year.html","content_en":{"title":"Celebrate the ways you connect","body":"There is no single way to play or communicate. Notice the small moments you and your baby enjoy, and bring questions or concerns to your health professional.","activity":"Choose a favorite shared song, book, or game and enjoy it together today."},"content_pt":{"title":"Celebre as formas como vocês se conectam","body":"Não existe uma única forma de brincar ou se comunicar. Observe os pequenos momentos que vocês apreciam e converse com um profissional de saúde se tiver dúvidas ou preocupações.","activity":"Escolha uma canção, livro ou brincadeira de que vocês gostam e aproveitem juntos hoje."}}
]
